('9fd7a71a-8dd3-5673-be14-72312a909ab4'::uuid, '2026-07-18'::date, $dq${}$dq$::jsonb, $dq${}$dq$::jsonb, $dq$[]$dq$::jsonb, $dq$[{"bft": 2, "ws": 2, "wg": 4, "wd": 142, "dir": "SE", "wv": 0.7, "waveDir": "WSW", "sst": 11.7, "tc": 11, "feels": 9, "pres": 1026, "presTrend": "steady", "cond": {"icon": "☁️", "desc": "Overcast", "code": 3}, "flag": "green", "ts": "2026-07-20T16:35", "time": "10:00", "retro": true}]$dq$::jsonb, $dq$Orri fixed stern light on Gróa. Warmed motor up ~1h, sailing with Hannes, Helgi Steinarr. Gummi, Eva, Rebekka +1, ÁMJ on zest, topper. Rowers: Íris Björg + Nora; Árna + Gunnur. Sindri +2 on kayaks paddleboards. Helgi + 2 on Zest?, kayaks. David, 1 new face (?! mother, son) on kayaks.$dq$, $dq${"h1t": "09:18", "h1h": "4.2", "l1t": "03:06", "l1h": "-0.1", "h2t": "21:36", "h2h": "4.1", "l2t": "15:24", "l2h": "0.2"}$dq$::jsonb, NULL, NULL, $dq$steve$dq$, '2026-07-20T16:39:47.636Z'::timestamptz, '2026-07-20T16:39:47.636Z'::timestamptz),
