('61bc85dd-18b8-59a7-8e58-94fc5da9576e'::uuid, '2026-07-21'::date, $dq${}$dq$::jsonb, $dq${}$dq$::jsonb, $dq$[]$dq$::jsonb, $dq$[{"bft": 2, "ws": 3, "wg": 4, "wd": 225, "dir": "SW", "wv": 1, "waveDir": "WSW", "sst": 11.7, "tc": 12, "feels": 11, "pres": 1026, "presTrend": "steady", "cond": {"icon": "🌧️", "desc": "Drizzle", "code": 51}, "flag": "green", "ts": "2026-07-22T11:43", "time": "09:00", "retro": true}, {"bft": 2, "ws": 2, "wg": 4, "wd": 232, "dir": "SW", "wv": 1, "waveDir": "WSW", "sst": 11.7, "tc": 13, "feels": 12, "pres": 1027, "presTrend": "steady", "cond": {"icon": "☁️", "desc": "Overcast", "code": 3}, "flag": "green", "ts": "2026-07-22T11:43", "time": "13:00", "retro": true}, {"bft": 2, "ws": 2, "wg": 5, "wd": 204, "dir": "SSW", "wv": 0.9, "waveDir": "W", "sst": 11.8, "tc": 13, "feels": 12, "pres": 1027, "presTrend": "steady", "cond": {"icon": "☁️", "desc": "Overcast", "code": 3}, "flag": "green", "ts": "2026-07-22T11:43", "time": "17:00", "retro": true}]$dq$::jsonb, $dq$LVS: rowboats to nauthólsvík; LASB 1Q, Y; FHB: Gummi, RLG on Quest (spin); rest on zests with beach challenge - no wind switched to slo-mo capsize. Stebba's first sail on Yngling. No rowers. HH: Þorbjörn + 1 showed, bailed (no wind); SDS worked with Jóhanna: 2x rigging yngling & carmen, line names, positions, uses. mocked tacks/gybes.$dq$, $dq${"h1t": "11:36", "h1h": "3.5", "l1t": "05:18", "l1h": "0.8", "h2t": "", "h2h": "", "l2t": "17:54", "l2h": "0.9"}$dq$::jsonb, NULL, NULL, $dq$steve$dq$, '2026-07-22T11:43:48.652Z'::timestamptz, '2026-07-22T11:43:48.652Z'::timestamptz),
