('8f004ec7-5235-532b-8cdb-45a6a2cec0ff'::uuid, '2026-08-04'::date, $dq${}$dq$::jsonb, $dq${}$dq$::jsonb, $dq$[]$dq$::jsonb, $dq$[{"bft": 2, "ws": 3, "wg": 6, "wd": 298, "dir": "WNW", "wv": 0.5, "waveDir": "W", "sst": 12.9, "tc": 11, "feels": 9, "pres": 1019, "presTrend": "steady", "cond": {"icon": "☁️", "desc": "Overcast", "code": 3}, "flag": "green", "ts": "2026-08-05T14:49", "time": "17:00", "retro": true}]$dq$::jsonb, $dq$SDS met with STÚM instructors kl. 10 to set weekend plan. Haukur, Gunnar S sailing mid-afternoon. ÁMJ, RLG on Optis. Sigga with Hörður, Jóhanna+1 on Yngling. Þorbjörn+1 on Carmen. Hermann, Éva on Quest. Sigga on Quest. Íris & Olga rowing.$dq$, $dq${"h1t": "10:06", "h1h": "4.0", "l1t": "03:54", "l1h": "0.3", "h2t": "22:30", "h2h": "3.8", "l2t": "16:18", "l2h": "0.4"}$dq$::jsonb, $dq$steve$dq$, '2026-08-04T13:42:42.778Z'::timestamptz, $dq$steve$dq$, '2026-08-04T13:41:32.932Z'::timestamptz, '2026-08-05T14:51:17.916Z'::timestamptz),
('4195ba80-6290-5e8f-81d5-369af8fbcff0'::uuid, '2026-09-01'::date, $dq${}$dq$::jsonb, $dq${}$dq$::jsonb, $dq$[]$dq$::jsonb, $dq$[]$dq$::jsonb, $dq$SV Tortuga (Gregor) arrived PM 31/8 - plans to be here week or more. Looking for uppsátur. Éva/Hermann on Yngling; Gunnar H., Þrúður on ILCAs; Sigga K. on kayak; Bjarni on Aero. Brought H & E into messenger group; discussed Ynglingasamband.$dq$, $dq${"h1t": "08:54", "h1h": "4.3", "l1t": "02:48", "l1h": "0.0", "h2t": "21:18", "h2h": "4.2", "l2t": "15:06", "l2h": "0.0"}$dq$::jsonb, $dq$steve$dq$, '2026-09-01T15:46:37.560Z'::timestamptz, $dq$steve$dq$, '2026-09-01T15:45:50.211Z'::timestamptz, '2026-09-02T15:28:34.787Z'::timestamptz),
